        Pyritohedron 2-3
        Other forms\Pyritohedron\Pyritohedron 2-3
        Bo HU
        Evgeniy Grigoriev, Boris
        2016-11-12
    

    
        clYellow       := 'FFFF00';
        clLightBlue    := '2828FF';
        clBlue         := '0000A0';
        clBrown        := '800000';
        clOrange       := 'FF6000';
        clLightViolett := 'FF0080';
        clRed          := 'FF0000';
        clLightGreen   := '00FF00';
        clGreen        := '008000';
        clViolett      := '800080';
        clCyan         := '00DCB4';
        clWhite        := 'FFFFFF';

        DCut := 0.55;

        // Solve(x^4 + x^3 - 2 * x^2 - x - 1 = 0 near x = 1.37)
        x := 1.373132853176455;
        ss := sin(arctan(x));
        cs := cos(arctan(x));
        D := DCut * (ss^3 - cs^3) / (cs - 3 * cs^2 * ss + cs * ss^2 + ss);

        A1 := ArcCos(ss * cs / (1 + cs * ss));       // A1 := Angle( ss, cs, 0,  cs,  0, ss,  0, ss, cs);
        A2 := ArcCos((ss^4 - cs^2) / (ss^4 + cs^2)); // A2 := Angle( ss, cs, 0,   0, ss,-cs,  0, ss, cs);
        A3 := A1 + A2;
        A4 := A1 + A2 + A1;
    

ss * cs * / (1 + cs * ss)
